CREATE OR REPLACE FUNCTION "product_changes"() RETURNS trigger AS $$
DECLARE
  written timestamptz := clock_timestamp();
BEGIN
  -- Writes a message of ProductChange for each write of a row of product
  -- its behaviors hear, whoever makes it (D103).
  IF TG_OP = 'UPDATE' AND NOT (OLD."title" IS DISTINCT FROM NEW."title" OR OLD."price" IS DISTINCT FROM NEW."price" OR OLD."note" IS DISTINCT FROM NEW."note" OR OLD."phase" IS DISTINCT FROM NEW."phase" OR OLD."phase_entered_at" IS DISTINCT FROM NEW."phase_entered_at") THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'INSERT' THEN
    INSERT INTO "product_change_queue" ("row_key", "write", "at", "before", "after", "due_at", "created_at")
    VALUES (NEW."id", 'insert', floor(extract(epoch FROM written) * 1000)::bigint, NULL, jsonb_build_object('title', NEW."title", 'price', NEW."price", 'note', NEW."note", 'phase', NEW."phase", 'phase_entered_at', NEW."phase_entered_at"), written, written);
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO "product_change_queue" ("row_key", "write", "at", "before", "after", "due_at", "created_at")
    VALUES (NEW."id", 'update', floor(extract(epoch FROM written) * 1000)::bigint, jsonb_build_object('title', OLD."title", 'price', OLD."price", 'note', OLD."note", 'phase', OLD."phase", 'phase_entered_at', OLD."phase_entered_at"), jsonb_build_object('title', NEW."title", 'price', NEW."price", 'note', NEW."note", 'phase', NEW."phase", 'phase_entered_at', NEW."phase_entered_at"), written, written);
  ELSE
    INSERT INTO "product_change_queue" ("row_key", "write", "at", "before", "after", "due_at", "created_at")
    VALUES (OLD."id", 'delete', floor(extract(epoch FROM written) * 1000)::bigint, jsonb_build_object('title', OLD."title", 'price', OLD."price", 'note', OLD."note", 'phase', OLD."phase", 'phase_entered_at', OLD."phase_entered_at"), NULL, written, written);
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql
